import json
# -*- coding: utf-8 -*- import os, sys, subprocess, numpy as np, soundfile as sf import librosa  FFMPEG_BIN = r"C:\Users\Administrator\miniconda3\envs\blackwell_env\Lib\site-packages\static_ffmpeg\bin\win32\ffmpeg.exe" os.environ["PATH"] = os.path.dirname(FFMPEG_BIN) + os.pathsep + os.environ["PATH"]  def run_v37_vad_cut():     print(f"\n[V37-VAD] 正在执行【能量探测】精准截断...")          script_path = r"E:\VideoTranslator_Project\separated_audio\V34_CRISP_SCRIPT.json"     audio_dir = r"E:\VideoTranslator_Project\temp_factory\v34_final_wavs"     output_p = r"E:\VideoTranslator_Project\output_final\V37_VAD_PRECISION_AUDIT.wav"          with open(script_path, "r", encoding="utf-8") as f: data = json.load(f)      # 目标：Seg 12     idx = 12     item = data[idx]     raw_p = os.path.join(audio_dir, f"raw_{idx}.wav")          # 1. 读取原始波形     y, sr = librosa.load(raw_p, sr=None)          # 2. 执行 VAD：寻找真正的发音结束点     # 我们使用更敏感的能量门限     intervals = librosa.effects.split(y, top_db=35) # 35dB 门限          if len(intervals) > 0:         # 取最后一个有效发音区间的终点         true_end_sample = intervals[-1][1]         true_end_time = true_end_sample / sr         print(f"  -> [VAD 报告]：检测到语音在 {true_end_time:.2f}s 处自然结束。")     else:         true_end_time = len(y) / sr      # 3. 执行“物理关闸”     # 我们多留 100ms 保证不生硬，然后强制淡出     final_end = true_end_time + 0.1          cmd_vad = [         FFMPEG_BIN, "-y", "-i", raw_p,         "-af", f"atrim=start=0.15:end={final_end+0.15},asetpts=PTS-STARTPTS,afade=t=out:st={max(0, final_end-0.1)}:d=0.1",         output_p     ]     subprocess.run(cmd_vad, check=True, capture_output=True)          print(f"✅ V37 精准截断完成。物理时长: {sf.info(output_p).duration:.2f}s")     print(f"🏆 试听路径: {output_p}")  if __name__ == "__main__":     run_v37_vad_cut()
